  format        char(8);
  API           char(10);
  crtDate       char(13);
  infStat       char(1);
  sizeUsrSpc    int(10);
  ofsInpSct     int(10);
  sizeInpSct    int(10);
  ofsHdrSct     int(10);
  sizeHdrSct    int(10);
  ofsLstSct     int(10);
  sizeLstSct    int(10);
  numE          int(10);
  sizeE         int(10);
  CCSID         int(10);
  cntryID       char(2);
